/* Studio One Academy · dependency-free, hash routed, offline-friendly. */
'use strict';
const stages = window.CURRICULUM;
const colors = ['#347bed','#9b6add','#e29839','#38a58b','#dd718b'];
const symbols = ['◉','≋','♬','☷','✧'];
const lessons = stages.flatMap((stage, si) => stage.lessons.map((lesson, li) => ({...lesson,stage,si,li,number:si*6+li+1})));
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = {read(key,fallback){try{return JSON.parse(localStorage.getItem(key)) ?? fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器未允许保存，本次进度仅保留在当前页面。');return false}}};
let completed = new Set(storage.read('s1-completed',[]));
let checks = storage.read('s1-checks',{});
let materialManifest = null;
let filterStage = 'all';
let theme = storage.read('s1-theme','light');
document.documentElement.dataset.theme = theme;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function waveform(seed){let bars='';for(let i=0;i<91;i++){const v=Math.abs(Math.sin(i*seed)*Math.cos(i*.29));const h=3+v*23;bars+=`<rect x="${i*3.3}" y="${(28-h)/2}" width="1.5" height="${h}" rx=".8"/>`}return `<svg viewBox="0 0 300 28" preserveAspectRatio="none" aria-hidden="true" fill="currentColor">${bars}</svg>`}
function artwork(){return `<div class="hero-art" aria-label="多轨音乐制作示意图"><div class="art-glow"></div><div class="daw-window"><div class="daw-toolbar"><i class="traffic"></i><i class="traffic"></i><i class="traffic"></i><span class="daw-title">MY FIRST TRACK.song</span><span>⌘</span></div><div class="transport"><span>↻</span><span class="play-icon">▶</span><strong>001.01.01</strong><span>100 BPM</span></div>${[['Drums','#d8e7ff','#6499e8',1.3],['Bass','#e6ddfa','#aa86df',.8],['Keys','#d6ede6','#69b49d',.3],['Melody','#f9e1d9','#dc9b84',.6]].map(([label,lane,c,seed])=>`<div class="track"><span class="track-label">${label}</span><div class="wave-lane" style="--lane:${lane};color:${c}">${waveform(seed)}</div></div>`).join('')}</div><div class="floating-chip"><span class="chip-check">✓</span><span><b>让灵感，成为作品。</b><small>FROM YOUR FIRST NOTE TO YOUR FIRST RELEASE</small></span></div></div>`}
function updateSidebar(){
 $('#course-nav').innerHTML=stages.map((s,i)=>`<details class="stage-nav" style="--stage:${colors[i]}" ${location.hash.includes(s.id)||s.lessons.some(l=>location.hash.includes('/'+l.id))?'open':''}><summary><span class="stage-dot"></span>${esc(s.title)}</summary>${s.lessons.map(l=>`<a class="lesson-link ${location.hash.split('?')[0]===`#/lesson/${l.id}`?'active':''}" href="#/lesson/${l.id}">${completed.has(l.id)?'<span class="done">✓</span>':''}${esc(l.title)}</a>`).join('')}</details>`).join('');
 $('#progress-count').textContent=`${completed.size} / ${lessons.length}`;
 $('#progress-fill').style.width=`${completed.size/lessons.length*100}%`;
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(location.hash.startsWith('#/materials')?'materials':location.hash.startsWith('#/library')||location.hash.startsWith('#/lesson')?'library':'home')));
}
function home(){const next=lessons.find(l=>!completed.has(l.id))||lessons[0];return `<section class="hero"><div><div class="eyebrow">A LITTLE PRACTICE. A LOT OF POSSIBILITY.</div><h1>从第一条音轨，<br>到<span>你的完整作品。</span></h1><p class="intro">一间为你准备的声音研习室。循序渐进掌握 Studio One，<br>把每一个知识点，变成听得见的进步。</p><div class="actions"><a class="button primary" href="#/lesson/${next.id}">${completed.size?'继续学习':'开始第一课'} <span>↗</span></a><a class="button" href="#/library">探索全部课程 <span>→</span></a></div><p class="hero-footnote">零基础友好 · 案例驱动 · 原创素材可下载 · 无需付费插件</p></div>${artwork()}</section><div class="stats"><div class="stat"><strong>5<small>个阶段</small></strong><span>从基础到高阶的完整路径</span></div><div class="stat"><strong>${lessons.length}<small>节课程</small></strong><span>每一课都有清晰的目标</span></div><div class="stat"><strong>${lessons.reduce((n,l)=>n+l.points.length,0)}<small>个案例</small></strong><span>边学边做，理解每个知识点</span></div><div class="stat"><strong>4<small>套素材</small></strong><span>WAV 分轨与 MIDI 下载</span></div></div><div class="section-heading"><div><h2>找到你的下一步。</h2><p>从容开始，按自己的节奏前进。</p></div><a class="text-link" href="#/library">查看完整目录 →</a></div><div class="path-grid">${stages.map((s,i)=>`<a class="path-card" href="#/library/${s.id}" style="--stage:${colors[i]}"><div class="card-top"><span class="stage-icon">${symbols[i]}</span><span class="stage-number">STAGE 0${i+1}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="card-meta"><span>${s.lessons.length} 节课程 · ${s.lessons.reduce((n,l)=>n+l.points.length,0)} 个知识点</span><span class="card-arrow">↗</span></div></a>`).join('')}<div class="practice-card"><span class="eyebrow">LEARN BY MAKING</span><h3>不是记住按钮。<br>是做出你的声音。</h3><p>下载同一套素材，跟着案例一步一步完成。</p><a class="text-link" href="#/materials">打开素材库 →</a></div></div><div class="feature-row"><div class="feature-panel"><span class="feature-symbol">↓</span><div><h3>练习所需，已经备好。</h3><p>原创节奏、混音分轨与 MIDI，免费取用。</p></div><a href="#/materials" aria-label="浏览素材库">↗</a></div><div class="feature-panel"><span class="feature-symbol">✓</span><div><h3>每一次进步，都有记录。</h3><p>勾选验收清单，完成课程后自动保存进度。</p></div><a href="#/guide" aria-label="阅读学习指南">↗</a></div></div>`}
function lessonRow(l){return `<a class="lesson-row" href="#/lesson/${l.id}" style="--stage:${colors[l.si]}"><span class="lesson-index">${completed.has(l.id)?'✓':String(l.number).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p></div><span class="row-end">${esc(l.duration)}<br>${l.points.length} 个案例 ↗</span></a>`}
function library(stageId){const chosen=stages.find(s=>s.id===stageId);filterStage=chosen?chosen.id:'all';return `<header class="page-head"><div class="eyebrow">THE LEARNING PATH</div><h1>${chosen?esc(chosen.title):'每一个阶段，都有方向。'}</h1><p>${chosen?esc(chosen.description):'30 节课程，90 个知识点案例。从软件入门、录音编辑到编曲、混音和作品交付，按顺序学习，也可以直接查找你需要的内容。'}</p></header><div class="filters" aria-label="筛选阶段"><a class="filter ${filterStage==='all'?'active':''}" href="#/library">全部课程</a>${stages.map(s=>`<a class="filter ${filterStage===s.id?'active':''}" href="#/library/${s.id}">${esc(s.title)}</a>`).join('')}</div>${stages.filter(s=>filterStage==='all'||s.id===filterStage).map(s=>`<section class="library-stage"><h2><span class="stage-dot" style="--stage:${colors[stages.indexOf(s)]}"></span>${esc(s.title)}</h2><div class="lesson-list">${lessons.filter(l=>l.stage.id===s.id).map(lessonRow).join('')}</div></section>`).join('')}`}
const assetNames={rhythm:'节奏练习包',vocal:'合成信号编辑包',mix:'混音分轨包',midi:'MIDI 练习包'};
function assetLink(key,label){return `<a href="assets/${key}.zip" download>${esc(label||'↓ 下载'+assetNames[key])}</a>`}
function lessonPage(id){const l=lessons.find(x=>x.id===id);if(!l)return notFound();const previous=lessons[l.number-2],next=lessons[l.number];const checked=checks[l.id]||[];return `<header class="lesson-head"><div class="eyebrow">STAGE 0${l.si+1} · LESSON ${String(l.number).padStart(2,'0')}</div><h1>${esc(l.title)}</h1><p>${esc(l.summary)}</p><div class="pill-row"><span class="pill">${esc(l.stage.title)}</span><span class="pill">建议 ${esc(l.duration)}</span><span class="pill">${l.points.length} 个知识点 · ${l.points.length} 个案例</span><span class="pill">${assetNames[l.asset]}</span></div></header><div class="lesson-layout"><article class="lesson-content"><div class="notice">通用操作以 Studio One 的 Song 工作流为基础；菜单名称、内置音源和高级功能因版本而异。遇到缺失功能请用软件帮助菜单查阅对应版本手册。练习素材统一为 100 BPM / 4⁄4 / 8 小节。</div>${l.points.map((p,i)=>`<section class="point" id="point-${i+1}"><h2><span class="point-index">${i+1}</span>${esc(p.title)}</h2><p>${esc(p.explanation)}</p><h3>动手操作</h3><ol>${p.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="example"><span class="example-label">CASE ${String(l.number).padStart(2,'0')}.${i+1} · 实践案例</span><h3>${esc(p.title)}：用一次对比听懂它</h3><p>${esc(p.example)}</p><p class="result"><strong>预期结果：</strong>${esc(p.result)}</p><div class="resource-inline">${assetLink(l.asset)}<a href="#assignment" data-anchor="assignment">查看本课验收清单 →</a></div></div><div class="pitfall"><strong>常见误区 · </strong>${esc(p.pitfall)}</div></section>`).join('')}<section class="assignment" id="assignment"><span class="eyebrow">MAKE IT YOURS</span><h2>把这一课，做成一次练习。</h2><p>${esc(l.exercise)}</p><h3>验收清单</h3>${l.checklist.map((item,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" data-lesson="${l.id}" ${checked.includes(i)?'checked':''}><span>${esc(item)}</span></label>`).join('')}<div class="actions"><button class="button primary" data-complete="${l.id}">${completed.has(l.id)?'✓ 已完成 · 点击取消':'标记本课完成 ✓'}</button><button class="button" id="print-lesson">打印 / 保存 PDF</button></div><p class="hero-footnote">进度保存在当前浏览器中。勾选清单用于自我验收，不代表系统已检查你的工程。</p></section><div class="lesson-bottom">${previous?`<a class="button" href="#/lesson/${previous.id}">← ${esc(previous.title)}</a>`:'<a class="button" href="#/library">← 课程目录</a>'}${next?`<a class="button" href="#/lesson/${next.id}">下一课 →</a>`:'<a class="button" href="#/library">返回课程目录 →</a>'}</div></article><aside class="lesson-toc" aria-label="本课目录"><strong>本课内容</strong>${l.points.map((p,i)=>`<a href="#point-${i+1}" data-anchor="point-${i+1}">0${i+1} · ${esc(p.title)}</a>`).join('')}<a href="#assignment" data-anchor="assignment">练习与验收</a><a class="button primary small" href="assets/${l.asset}.zip" download>↓ 下载本课素材</a><a href="#/guide">版本差异与参考资料 ↗</a></aside></div>`}
function materials(){return `<header class="page-head"><div class="eyebrow">YOUR PRACTICE TOOLKIT</div><h1>好练习，从好素材开始。</h1><p>四套项目自带的原创素材。所有音频算法生成，可下载、拆解、修改和再创作。无需注册，也不依赖外部网盘。</p></header><div class="download-all"><div><h2>一次下载，开始整套练习。</h2><p>包含全部 WAV、MIDI 与每套素材说明 · ZIP 约 10.8 MB · CC0</p></div><a class="button primary" href="assets/all-materials.zip" download>下载完整素材包 ↓</a></div><div class="material-grid">${Object.entries(materialManifest||{}).map(([key,m],i)=>`<section class="material-card" style="--stage:${colors[i]}"><span class="stage-icon">${['≋','◉','☷','♬'][i]}</span><h2>${esc(m.title)}</h2><div class="material-meta">${m.bpm} BPM · 4/4 · 8 小节 · 19.2 秒 · ${key==='midi'?'Standard MIDI':'44.1 kHz / 16-bit / Mono'}</div><p>${esc(m.description)}</p>${key==='rhythm'||key==='mix'?`<audio controls preload="none" src="assets/${key}-preview.wav" aria-label="${esc(m.title)}试听"></audio>`:''}<ul>${m.files.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><div class="actions"><a class="button primary small" href="${esc(m.file)}" download>下载 ZIP ↓</a><a class="text-link" href="#/lesson/${lessons.find(l=>l.asset===key)?.id||lessons[0].id}">从相关课程开始 →</a></div></section>`).join('')}</div><div class="notice"><strong>素材使用说明：</strong>解压 ZIP 后，将 WAV 拖入音频轨，所有分轨从第 1 小节起对齐；MIDI 拖入后加载音源，鼓 MIDI 使用 GM 鼓映射。合成人声式信号不含真人演唱，只适合编辑、音量和噪声辨识；气息、齿音、真实录音与修音练习需用你本人录制或已获授权的人声。CC0 仅覆盖本项目生成的练习素材。</div>`}
function guide(){return `<header class="page-head"><div class="eyebrow">A FEW THINGS BEFORE YOU START</div><h1>让每次练习，都有收获。</h1><p>这是一份独立编写的中文学习手册，面向 Studio One 的通用音乐制作流程。以实际软件和对应版本的官方手册为准。</p></header><article class="guide"><section><h2>01 · 建议的学习方法</h2><ul><li>从入门阶段依次学习；每课安排 45–90 分钟，将操作与听音分开练习。</li><li>解压素材并建立 100 BPM、4/4 的 Song，分轨统一从第 1 小节开始。另存为新工程再编辑。</li><li>先做不加效果的版本，再只改变一个参数，用相近响度比较 A/B。写下听到的变化。</li><li>完成验收清单后标记课程完成。最终以能够独立重复操作、解释原因和导出结果为标准。</li></ul></section><section><h2>02 · 版本与功能差异</h2><p>课程沿用 Studio One 名称和常见 Song 工作流。官方在线手册目前跳转至 Fender Studio Pro 手册；旧版 Studio One 用户应优先打开自己软件中安装的参考手册。音频接口驱动、低延迟监听、音源、和弦功能、Project 页面、ARA 与第三方修音工具可能受系统、版本和授权限制。</p><p>不存在某个按钮时，先在本机帮助菜单搜索功能关键词。课程中的参数是练习起点，不是固定预设；相同参数在不同素材上会产生不同结果。</p><a href="https://support.presonus.com/hc/en-us/articles/42529985007501-Where-To-Find-the-Fender-Studio-Pro-Manual" target="_blank" rel="noopener">官方：安装与打开参考手册 ↗</a></section><section><h2>03 · 官方参考来源</h2><ul><li><a href="https://s1manual.presonus.com/" target="_blank" rel="noopener">Studio One / Studio Pro 在线参考手册</a>：查阅音频设备、编辑、乐器、效果器与导出功能。当前地址会重定向到 Fender 官方手册。</li><li><a href="https://support.presonus.com/" target="_blank" rel="noopener">PreSonus 官方知识库</a>：设备与安装问题按软件版本搜索。</li><li><a href="https://developer.apple.com/design/human-interface-guidelines/materials" target="_blank" rel="noopener">Apple Human Interface Guidelines · Materials</a>：界面参考。本站使用网页技术演绎玻璃材质和分层导航，并非 Apple 官方应用。</li></ul><p>课程内容为原创教学说明，并非复制官方手册。参考链接核验日期：2026-10-25。</p></section><section><h2>04 · 素材与项目许可</h2><p>程序代码使用 MIT 许可。课程文字使用 CC BY 4.0，转载需注明“Studio One · 声音研习室”。本项目算法生成的 WAV 与 MIDI 素材使用 CC0，可自由修改和用于作品。各素材包内附用途与限制；不包含厂商收费音源、商业歌曲或第三方教学工程。</p><p>这是独立学习项目，与 Apple、PreSonus、Fender 无隶属或背书关系。软件与品牌名称属于相应权利人。</p></section><section><h2>05 · 保存学习进度</h2><p>完成状态、验收清单与主题设置保存在当前浏览器的本地存储中；不会上传，也不会跨设备同步。清除浏览器数据后会丢失。可以导出 JSON 备份，再在另一台设备导入。</p><div class="actions"><button class="button" id="export-progress">导出学习进度 ↓</button><label class="button" for="import-progress" tabindex="0">导入学习进度 ↑</label><input type="file" id="import-progress" accept="application/json,.json" hidden></div></section></article>`}
function notFound(){return `<header class="page-head"><h1>这一页还没有声音。</h1><p>链接可能已经变更，请从课程目录重新选择。</p><a class="button primary" href="#/library">返回课程目录 →</a></header>`}
function route(){const hash=location.hash||'#/';if(!hash.startsWith('#/')){const anchor=document.getElementById(hash.slice(1));if(anchor){anchor.scrollIntoView();return}}const parts=hash.replace(/^#\//,'').split('/');const [page,id]=parts;const title=page==='lesson'?lessons.find(l=>l.id===id)?.title:page==='library'?'完整课程':page==='materials'?'案例素材库':page==='guide'?'使用指南':'学习总览';$('#breadcrumb').innerHTML=`研习室 <span>/</span> ${esc(title||'未找到课程')}`;$('#main').innerHTML=page==='lesson'?lessonPage(id):page==='library'?library(id):page==='materials'?materials():page==='guide'?guide():page?notFound():home();document.title=`${title||'课程'} · Studio One 声音研习室`;updateSidebar();closeMenu();window.scrollTo({top:0,behavior:'instant'});if(page==='lesson')storage.write('s1-last',id);}
function closeMenu(){$('#sidebar').classList.remove('open');$('#shade').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#shade').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open))});$('#shade').addEventListener('click',closeMenu);
$('#theme-toggle').addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;storage.write('s1-theme',theme)});
document.addEventListener('click',event=>{const anchor=event.target.closest('[data-anchor]');if(anchor){event.preventDefault();document.getElementById(anchor.dataset.anchor)?.scrollIntoView({behavior:'smooth'});return}const done=event.target.closest('[data-complete]');if(done){const id=done.dataset.complete;completed.has(id)?completed.delete(id):completed.add(id);storage.write('s1-completed',[...completed]);done.textContent=completed.has(id)?'✓ 已完成 · 点击取消':'标记本课完成 ✓';updateSidebar();toast(completed.has(id)?'已记录，继续向你的作品前进。':'已取消完成状态。')}if(event.target.closest('#print-lesson'))window.print();if(event.target.closest('#export-progress')){const blob=new Blob([JSON.stringify({version:1,completed:[...completed],checks},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='studio-one-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}});
document.addEventListener('change',async event=>{if(event.target.matches('[data-check]')){const id=event.target.dataset.lesson;const n=Number(event.target.dataset.check);const set=new Set(checks[id]||[]);event.target.checked?set.add(n):set.delete(n);checks[id]=[...set];storage.write('s1-checks',checks)}if(event.target.id==='import-progress'&&event.target.files[0]){try{const file=event.target.files[0];if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.completed)||typeof data.checks!=='object'||data.checks===null)throw Error();completed=new Set(data.completed.filter(id=>lessons.some(l=>l.id===id)));checks={};for(const l of lessons){const list=data.checks[l.id];if(Array.isArray(list))checks[l.id]=list.filter(i=>Number.isInteger(i)&&i>=0&&i<l.checklist.length)}storage.write('s1-completed',[...completed]);storage.write('s1-checks',checks);updateSidebar();toast('学习进度已导入。')}catch{toast('导入失败，请选择本网站导出的进度 JSON。')}}});
const dialog=$('#search-dialog');function showSearch(){dialog.showModal();$('#search-input').value='';search('');$('#search-input').focus()}$('#search-open').addEventListener('click',showSearch);$('#search-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!dialog.open)showSearch()}if(e.key==='Escape')closeMenu()});
function search(query){const q=query.trim().toLowerCase();const found=q?lessons.filter(l=>JSON.stringify([l.title,l.summary,l.points]).toLowerCase().includes(q)):lessons.slice(0,5);$('#search-results').innerHTML=found.length?found.map(l=>`<a class="search-result" href="#/lesson/${l.id}"><strong>${esc(l.title)}</strong><small>${esc(l.stage.title)} · ${esc(l.summary)}</small></a>`).join(''):`<p class="search-empty">没有找到相关内容。试试“压缩”“录音”或“导出”。</p>`}$('#search-input').addEventListener('input',e=>search(e.target.value));$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))dialog.close()});
window.addEventListener('hashchange',route);
route();
fetch('assets/manifest.json').then(r=>{if(!r.ok)throw Error('manifest');return r.json()}).then(data=>{materialManifest=data;if(location.hash.startsWith('#/materials'))route()}).catch(()=>{materialManifest=Object.fromEntries(Object.entries(assetNames).map(([key,title])=>[key,{title,file:`assets/${key}.zip`,description:'项目自带原创练习素材，解压后阅读 README。',bpm:100,files:['详细清单见 ZIP 内 README']} ]));if(location.hash.startsWith('#/materials'))route()});
